-- =====================================================================
-- Carga de datos: Matemática 3° básico · Capítulo 11 "Pictogramas y gráficos de barra"
-- Fuente: Texto del estudiante de Matemática 3° básico (cap. 11, págs. 388-421)
-- Ejecutar DESPUÉS de schema.sql. Se puede volver a ejecutar sin duplicar datos.
-- No se copian los textos del libro: cada actividad tiene una descripción propia y,
-- en `recurso`, un JSON con la referencia de página y los datos numéricos de la actividad.
-- Los valores marcados "valores_leidos_del_grafico": true se leyeron de los gráficos
-- del libro (no venían en una tabla): conviene revisarlos.
-- =====================================================================
USE plataforma_educativa;

-- Limpieza para poder re-ejecutar el script (borra solo lo del capítulo 11)
DELETE FROM contenido WHERE JSON_VALID(recurso) AND JSON_EXTRACT(recurso, '$.capitulo') = 11;

-- Objetivo de Aprendizaje (Bases Curriculares MINEDUC, Matemática 3° básico, Datos y probabilidades)
ON DUPLICATE KEY UPDATE descripcion = VALUES(descripcion);

SET @oa = (SELECT id_oa FROM objetivo_aprendizaje WHERE codigo_oa = 'OA 25');

SET @t_enc = (SELECT id_tipo FROM tipo_contenido WHERE nombre_tipo = 'Encuesta y tabla de datos');
SET @t_con = (SELECT id_tipo FROM tipo_contenido WHERE nombre_tipo = 'Conocimiento de gráficos');
SET @t_int = (SELECT id_tipo FROM tipo_contenido WHERE nombre_tipo = 'Interpretación de gráficos');
SET @t_cre = (SELECT id_tipo FROM tipo_contenido WHERE nombre_tipo = 'Creación de gráficos');


-- Vincular todas las actividades del capítulo 11 con el OA 25
SELECT id_contenido, @oa FROM contenido
WHERE JSON_VALID(recurso) AND JSON_EXTRACT(recurso, '$.capitulo') = 11;

-- Verificación: cantidad de actividades por etapa (debe sumar 36)
SELECT t.nombre_tipo AS etapa, COUNT(*) AS actividades
FROM contenido c JOIN tipo_contenido t ON t.id_tipo = c.id_tipo
GROUP BY t.nombre_tipo;
